<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Form W-3 (2026)</title>
<style>
    body {
        font-family: Arial, Helvetica, sans-serif;
        font-size: 11px;
        line-height: 1.2;
        margin: 0;
        padding: 20px;
        box-sizing: border-box;
        background-color: white;
    }
    .container {
        max-width: 850px;
        margin: 0 auto;
    }
    .do-not-staple {
        color: #d9261c;
        font-weight: bold;
        text-align: center;
        font-size: 16px;
        margin-bottom: 5px;
    }
    table.w3-form {
        width: 100%;
        border-collapse: collapse;
        border: 3px solid black;
        margin-bottom: 5px;
    }
    table.w3-form td {
        border: 1px solid #d9261c;
        padding: 3px 5px;
        vertical-align: top;
        position: relative;
    }
    .label {
        color: #d9261c;
        font-size: 9px;
        display: block;
    }
    .val-box {
        font-size: 18px;
        font-family: monospace;
        font-weight: bold;
        text-align: center;
