<div class="container">
    <div class="do-not-staple">DO NOT STAPLE</div>

    <table class="w3-form">
        <tr>
            <td style="width: 15%; border-right: 1px solid #d9261c;">
                <div class="val-box">33333</div>
            </td>
            <td style="width: 35%;">
                <span class="label">a Control number</span>
            </td>
            <td colspan="2" style="width: 50%;">
                <span class="label" style="font-weight: bold;">For Official Use Only:</span>
                <span class="label" style="font-weight: bold;">OMB No. 1545-0029</span>
            </td>
        </tr>
        <tr>
            <td colspan="2" class="dashed-right">
                <div style="display: flex; justify-content: flex-start; align-items: baseline;">
                    <span class="label" style="margin-right: 10px;">b</span>
                    <div>
                        <span class="label" style="font-weight: bold; font-size: 10px; display: inline;">Kind of Payer</span>
                        <span class="label" style="display: inline; margin-left: 5px;">(Check one)</span>
                    </div>
                </div>
                <div style="display: flex; gap: 20px; margin-top: 8px; padding-left: 20px;">
                    <div class="checkbox-item">941<div class="checkbox"></div></div>
                    <div class="checkbox-item">Military<div class="checkbox"></div></div>
                    <div class="checkbox-item">943<div class="checkbox"></div></div>
                    <div class="checkbox-item">944<div class="checkbox"></div></div>
                </div>
                <div style="display: flex; gap: 20px; margin-top: 8px; padding-left: 20px;">
                    <div class="checkbox-item">CT-1<div class="checkbox"></div></div>
                    <div class="checkbox-item">Hshld.<br>emp.<div class="checkbox"></div></div>
                    <div class="checkbox-item">Medicare<br>govt. emp.<div class="checkbox"></div></div>
                </div>
            </td>
            <td class="dashed-right">
                <span class="label" style="font-weight: bold; font-size: 10px; display: inline;">Kind of Employer</span>
                <span class="label" style="display: inline; margin-left: 5px;">(Check one)</span>
                <div style="display: flex; gap: 15px; margin-top: 8px; justify-content: center;">
                    <div class="checkbox-item">None apply<div class="checkbox"></div></div>
                    <div class="checkbox-item">501c non-govt.<div class="checkbox"></div></div>
                </div>
                <div style="display: flex; gap: 15px; margin-top: 8px; justify-content: center;">
                    <div class="checkbox-item">State/local<br>non-501c<div class="checkbox"></div></div>
                    <div class="checkbox-item">State/local 501c<div class="checkbox"></div></div>
                    <div class="checkbox-item">Federal govt.<div class="checkbox"></div></div>
                </div>
            </td>
            <td>
                <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%;">
                    <span class="label" style="text-align: center;">Third-party<br>sick pay</span>
                    <span class="label" style="text-align: center; margin-top: 2px;">(Check if<br>applicable)</span>
                    <div class="checkbox" style="margin-top: 5px;"></div>
                </div>
            </td>
        </tr>
        <tr>
            <td class="h-med"><span class="label">c Total number of Forms W-2</span></td>
            <td><span class="label">d Establishment number</span></td>
            <td style="width: 25%;"><span class="label">1 Wages, tips, other compensation</span></td>
