            <td colspan="2" class="h-med"><span class="label">h Other EIN used this year</span></td>
            <td><span class="label">13 For third-party sick pay use only</span></td>
            <td class="pink-bg"><span class="label">12b</span></td>
        </tr>
        <tr>
            <td class="h-med"><span class="label">15 State</span></td>
            <td><span class="label">Employer's state ID number</span></td>
            <td colspan="2"><span class="label">14 Income tax withheld by payer of third-party sick pay</span></td>
